// Test network connectivity to rendering services via fetch.
const results = {};

async function probe(name, url, opts) {
  try {
    const res = await fetch(url, opts);
    const text = await res.text();
    results[name] = { status: res.status, ok: res.ok, len: text.length, head: text.slice(0, 120) };
  } catch (e) {
    results[name] = { error: String(e) };
  }
}

await Promise.allSettled([
  probe('plantuml_get', 'https://www.plantuml.com/plantuml/svg/~1'),
  probe('kroki_root', 'https://kroki.io/'),
  probe('example', 'https://example.com/'),
]);

return results;

